#!/usr/bin/env bash
# Asset generation for Cloudberry. One preamble, verbatim, in every prompt.
# usage: bash gen.sh <name>   (see the case list below)
set -euo pipefail
cd "$(dirname "$0")"
KIE="C:/Users/ASUS/.claude/plugins/cache/nateherk/nateherk-design/0.3.0/skills/scroll-craft/scripts/kie.mjs"

PRE="Cinematic night photography inside an intimate bar and live-music venue, shot on a 35mm anamorphic lens with shallow depth of field. Practical light sources only: warm amber tungsten bulbs, a deep magenta-red neon glow and cold cyan light from phone screens. Deep blue-black shadows, rich saturated highlights, light haze in the air catching the beams, visible 35mm film grain, subtle anamorphic flare. Colour grade: ink blue-black, cloudberry orange-amber, neon magenta accents. Photographic realism, candid moment, real people with natural imperfect skin. NOT 3D render, NOT illustration, NOT CGI, NOT clay. No text, no letters, no numbers, no logos, no readable signage, no watermark, no plastic sheen."

still() { node "$KIE" still "$PRE

$2" "out/$1.png" "${@:3}"; }

case "$1" in
  hero) still 01-hero "A tired, irritated bar manager in his mid thirties with dark stubble and a black shirt sits behind a small dark wooden host desk near the entrance of an empty bar on an event night. He presses a smartphone to his ear, frowning, his other hand rubbing his forehead in frustration, an open paper reservation book and a small brass desk lamp on the desk in front of him. He is framed from the chest up, positioned right of centre at about two thirds of the frame width, the desk covering his lower body. Behind him the bar room is completely empty and dim: small round tables with unlit candles and empty chairs, a tiny stage with a drum kit waiting in the far background, a deep magenta-red neon tube glowing along the back wall. Large dark empty space across the whole left half of the frame for a headline. Medium shot, eye level, the whole head and both hands fully inside the frame with generous margins." --ar 16:9 ;;
  phone) still 02-phone "Close-up of a smartphone lying face up on a dark polished wooden bar counter in an almost completely dark, empty bar. Its blank screen glows with soft cold cyan light that spills across the glossy wood. A round cardboard coaster and a half empty glass sit beside it. Deep black shadows everywhere else, a faint magenta neon reflection far in the out of focus background. The phone lies in the lower left third of the frame; wide empty dark space above and to the right. Angled view from above at about 40 degrees. The screen shows no interface, only an even glow." --ar 16:9 ;;
  guest) still 03-guest "A smiling young woman in her late twenties wearing a dark wool coat stands just inside the entrance door of a bar at night, holding her smartphone up toward the camera with its glowing blank screen facing us, confident and friendly. Cold blue rainy street light behind her through the open door, warm amber bulb light from inside the bar on her face, a hint of magenta neon on her hair. Framed from the waist up, subject centred, both hands and the full phone inside the frame, empty dark space above her head." --ar 3:4 ;;
  arrive1) still 04-arrive-1 "A group of five friends in their late twenties walking into a bar at night through a doorway, laughing mid conversation, one of them holding up a phone, jackets and scarves, candid motion. Warm amber light inside, magenta neon edge light on their shoulders, haze. Framed from the waist up, the group centred, empty dark space above." --ar 3:4 ;;
  arrive2) still 04-arrive-2 "A couple in their thirties following a waiter in a black apron to a small candlelit table in a busy bar at night, the woman glancing back over her shoulder with a smile, a blank folded white card standing on the table. Warm bulbs overhead, cyan and magenta highlights in the blurred background crowd. Subjects centred, framed from the knees up, empty dark space above." --ar 3:4 ;;
  arrive3) still 04-arrive-3 "Four friends celebrating a birthday settling into a deep leather booth in a bar at night, one raising a glass toward the others, a waiter setting down a tray of orange cocktails, warm amber bulbs and a magenta neon glow behind them, haze. The group centred in the lower two thirds, empty dark space above." --ar 3:4 ;;
  full) still 05-full "Wide shot of a packed bar and live-music venue on an event night. Every table is full of people talking and laughing, a drummer and a double bass player perform on a small stage at the back under warm amber spotlights with haze in the beams, waiters carry trays of cocktails between the tables, strings of warm bulbs overhead, a magenta-red neon tube along the back wall. In the middle distance the bar manager in a black shirt stands with one arm raised, directing two waiters. Joyful, crowded, alive. Camera slightly above head height looking across the room. A darker calmer band of shadow along the bottom quarter of the frame for a headline." --ar 16:9 ;;
  fg) still 01-fg "Extreme foreground element only: the heavily out of focus rim of a bar counter with three empty cocktail glasses and a bottle neck, rendered as soft bokeh, their edges catching bright magenta neon and warm amber rim light. The glasses occupy the bottom right corner of the frame. Everything else in the frame is pure flat black with no detail." --ar 16:9 ;;
  plate) still 01-plate "Take the reference photograph and remove the man and the host desk completely. Rebuild the empty bar room behind where they were: small round tables with unlit candles, empty chairs, the floor, the back wall with the magenta-red neon tube, the tiny stage with the drum kit. Keep exactly the same camera position, framing, perspective, lens, lighting and colour grade. Nothing else changes." --ar 16:9 --ref out/01-hero.png ;;
  confused) still 03-confused "The same man as in the reference photograph, same face, stubble, haircut and black shirt. Close-up portrait: he holds a smartphone in front of his chest and stares down at its glowing screen with a confused, puzzled expression, one eyebrow raised, lips slightly parted. Lit from below by cold cyan screen light and from the side by warm amber bulbs, the dark bar blurred behind him. Subject centred, the full head and the phone inside the frame, empty dark space above his head. The phone screen faces away from the camera." --ar 3:4 --ref out/01-hero.png ;;
  empty) still 05-empty "Take the reference photograph and make the room completely empty: remove every person, the musicians and the waiters. Keep the same tables, chairs, stage, instruments standing on the stage, bulbs and neon tube. Candles unlit, the room dimmer and colder, only the magenta-red neon and a few bulbs on. Exactly the same camera position, framing, perspective and lens. Nothing else changes." --ar 16:9 --ref out/05-full.png ;;
  *) echo "unknown asset: $1"; exit 1 ;;
esac
